class oam_kpi_calculations(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self.search_start_timestamp = None
        self.search_end_timestamp = None
        self.results = {}
        self.latest_results = {}
        self.avg_results = {}
        self._log_warning = True
        self._calculator = None
        self._serial_console_connected = False

    @property
    def log_warning(self):
        return self._log_warning

    @log_warning.setter
    def log_warning(self, value):
        """
        Enable/Disable logging warning during kpi calculation
        :param bool, value: True/False
        """
        self._log_warning = value

    @property
    def serial_console_connected(self):
        return self._serial_console_connected

    @serial_console_connected.setter
    def serial_console_connected(self, value):
        """
        Sets the status of the serial console connection.
        :param bool, value: The status of the serial console connection. Default False
        :return: None
        """
        self.set_serial_console_connection_status(value)

    def set_serial_console_connection_status(self, value=False):
        """
        Sets the status of the serial console connection.
        :param bool, value: The status of the serial console connection. Default False
        :return: None
        """
        self._serial_console_connected = value

    def save_search_start_timestamp(self, time=None):
        """
        Save start timestamp. Only IMS records >= are taken to parser.
        :param datetime, str time: Optional - if not passed current time is used. Ypu can pass as datetime object or
                as string in ISO format eg: '2022-05-19T12:00:15.699000'
        :return: None
        """
        if time is None:
            self.search_start_timestamp = self._get_current_utc_time()
        else:
            self.search_start_timestamp = get_timestamp_in_datetime_format(time)

    def save_search_end_timestamp(self, time=None):
        """
        Save end timestamp. Only IMS records <= are taken to parser.
        :param datetime, str time: Optional - if not passed current time is used. Ypu can pass as datetime object or
                as string in ISO format eg: '2022-05-19T12:00:15.699000'
        :return: None
        """
        if time is None:
            self.search_end_timestamp = self._get_current_utc_time()
        else:
            self.search_end_timestamp = get_timestamp_in_datetime_format(time)

    def calculate_kpis(self, kpi_names, ims_file_path, kpi_params=None, merge_ims_files=False):  # noqa: C901
        """
        Calculate KPIs in parallel way.
            Supported KPIs:
                KPI1a, KPI1b, KPI1c
                KPI2a, KPI2b, KPI2c, KPI2d
                KPI3
                KPI4
                KPI5
                KPI7, KPI8, KPI9, KPI10
                KPI12
                KPI16a, KPI16b
                KPI17a, KPI17b
                KPI41
                KPI42
                KPI51a, KPI51b
                KPI54a, KPI54b
        :param list,str kpi_names: list of kpi names.
                Can be passed as string separated by whitespace as well . eg 'kpi1a kpi1b kpi1c'
        :param str, list ims_file_path: Path to IMS file(or list of ims paths).
        :param dict kpi_params:  additional KPI params. eg:
            cell_dist_names:  list of cell dist names to be considered in the calculation.
                              If None then all available cells will be used.
        :param bool merge_ims_files:  True/False - merge all IMS files into one IMS file before calculations.
        :return dict: calculated results for each KPI
        """
        all_exceptions = []
        logging.debug("Calculating {} from {}".format(kpi_names, ims_file_path))
        if kpi_params:
            logging.debug("KPI PARAMS: {}".format(kpi_params))
        if self.search_start_timestamp:
            logging.debug("search_start_timestamp is set to: {}".format(self.search_start_timestamp))
        if self.search_end_timestamp:
            logging.debug("search_end_timestamp is set to: {}".format(self.search_end_timestamp))

        self._calculator = IMSCalculator(kpi_names=kpi_names, kpi_params=kpi_params, ims_file_path=ims_file_path,
                                         log_warning=self.log_warning,
                                         serial_console_connected=self.serial_console_connected,
                                         merge_ims_files=merge_ims_files)
        self._calculator.calculate(search_start_timestamp=self.search_start_timestamp,
                                   search_end_timestamp=self.search_end_timestamp)

        self.latest_results = {}
        for kpi in self._calculator.kpis:
            own_kpi_name = kpi_params[kpi.name.lower()].get('kpi_name') if kpi_params else None
            kpi_name = own_kpi_name if own_kpi_name else kpi.name.lower()
            logging.debug("Results for {}: {}".format(kpi_name, kpi.iteration_results))
            if kpi.exception_msg:
                all_exceptions.extend(kpi.exception_msg)
            if kpi_name not in self.results:
                self.results[kpi_name] = []
            if kpi_name not in self.latest_results:
                self.latest_results[kpi_name] = []
            self.results[kpi_name].extend(kpi.iteration_results)
            self.latest_results[kpi_name].extend(kpi.iteration_results)

        if all_exceptions:
            raise OamKpiCalculationsException("Calculation Failed.\n{}".format(all_exceptions))

        not_calculated_kpis = self._validate_not_calculated_kpis()
        if not_calculated_kpis:
            raise OamKpiCalculationsException("One of the calculated KPIs is empty - please check details.\n{}".
                                              format("\n".join(not_calculated_kpis)))
        return self.results

    def calculate_kpi_from_swdl_report(self, kpi_names, swdl_report_file_path):
        """
        Calculate KPIs from SWDL report.
        :param list,str kpi_names: list of kpi names.
                Can be passed as string separated by whitespace as well
        :param str swdl_report_file_path: Path to SWDL report file.
        :return dict: calculated results for each KPI
        """
        self._calculator = SWDLCalculator(kpi_names=kpi_names, file_path=swdl_report_file_path)
        self._calculator.calculate()
        for kpi in self._calculator.kpis:
            kpi_name = kpi.name.lower()
            if kpi_name not in self.results:
                self.results[kpi_name] = []
            self.results[kpi_name].extend(kpi.results)

        return self.results

    def calculate_kpi_from_soap_files(self, kpi_names, start_point_file_path, end_point_file_paths, bts_info):
        """
        Calculate KPIs from SOAP and start-point log files (same shape as SWDL flow).

        :param list,str kpi_names: list of KPI names (or string with whitespace-separated names).
        :param str start_point_file_path: path to file with start points (e.g. log with API_CPRI_STATE_IND_MSG).
        :param list,str end_point_file_paths: path to SOAP file or list of SOAP file paths.
        :param dict bts_info: BTS info dict (e.g. from ru_soap) containing "cables" for connector–RMOD mapping.
        :return dict: calculated results for each KPI (key: kpi name lowercased).
        """
        if not isinstance(kpi_names, (list, tuple)):
            kpi_names = re.split(r'\s+', str(kpi_names).strip())
        kpi_names = [name.lower() for name in kpi_names if name]

        self._calculator = None
        for kpi_name in kpi_names:
            calculator = SOAPCalculator(
                kpi_name=kpi_name,
                start_point_file_path=start_point_file_path,
                end_point_file_paths=end_point_file_paths,
                bts_info=bts_info,
            )
            calculator.calculate(
                search_start_timestamp=self.search_start_timestamp,
                search_end_timestamp=self.search_end_timestamp,
            )
            if kpi_name not in self.results:
                self.results[kpi_name] = []
            self.results[kpi_name].extend(calculator.kpi.results)
            self._calculator = calculator

        return self.results

    def _validate_not_calculated_kpis(self):
        not_calculated_kpis = []
        for kpi in self._calculator.kpis:
            if not kpi.iteration_results:
                try:
                    kpi._validate_entries()
                except DataNotAvailable as e:
                    msg = "Cannot calculate {} due to: {}".format(kpi.name, repr(e))
                    not_calculated_kpis.append(msg)
        return not_calculated_kpis

    def save_results_to_file(self, file_path):
        """
        Save currently calculated KPIs to file(in JSON format)
        :param file_path: path to file
        :return: None
        """

        with open(file_path, 'w') as f:
            f.write(json.dumps(self.results, indent=4, sort_keys=True, default=custom_json_serializable))

    def save_all_alarm_events_to_file(self, file_path):
        if self._calculator:
            self._calculator.alarm.save_all_alarm_events_to_file(file_path)
        else:
            raise UserWarning("Please first calculate some KPI and then try to use this method.")

    def clear_results(self):
        """
        Clear current results.
        :return: None
        """
        self.search_start_timestamp = None
        self.search_end_timestamp = None
        self.results = {}
        self.latest_results = {}
        self.avg_results = {}

    def get_results(self, kpi_name=None):
        """
        Get full current results.
        :return dict: calculated results for each KPI
        """
        if kpi_name:
            return self.results[kpi_name.lower()]

        return self.results

    def get_latest_results(self, kpi_name=None):
        """
        Get latest calculated results.
        :return dict: calculated results for each KPI
        """
        if kpi_name:
            return self.latest_results[kpi_name.lower()]

        return self.latest_results

    def get_all_deltas(self, kpi_name, skip_none=False):
        """
        Get calculated delta.
        :param kpi_name: KPI name
        :param skip_none: True/False - skip none values from the list
        :return:
        """
        all_deltas = []
        for record in self.results[kpi_name.lower()]:
            if record['delta']:
                all_deltas.append(record['delta'].total_seconds())
            elif not skip_none:
                all_deltas.append(None)

        return all_deltas

    def get_average_results(self, kpi_name=None):
        """
        Calculate average values from all results.
        :param kpi_name: KPI name
        :return:
        """
        for _kpi_name in self.results:
            if kpi_name is None or (kpi_name and kpi_name.lower() == _kpi_name):
                deltas = self.get_all_deltas(kpi_name=_kpi_name, skip_none=True)
                logging.debug("All deltas for {}: {}".format(_kpi_name, deltas))
                average = sum(deltas) / len(deltas)
                self.avg_results[_kpi_name] = round(average, 2)

        if kpi_name:
            return self.avg_results[kpi_name.lower()]

        return self.avg_results

    def get_max_delta(self, kpi_name):
        """
        Get max delta from all iterations.
        :param kpi_name: KPI name
        :return:
        """
        return max(self.get_all_deltas(kpi_name.lower(), skip_none=True))

    def get_deltas_above_threshold(self, kpi_name, threshold):
        """
        Get max delta from all iterations.
        :param kpi_name: KPI name
        :param threshold: threshold in seconds
        :return:
        """
        return [delta for delta in self.get_all_deltas(kpi_name.lower(), skip_none=True) if delta > threshold]

    def update_device_info_in_latest_iteration(self, kpi_name, value):
        """
        In specific cases device info is not gathered automatically.
        This method allows to update `device_info` manually in latest iteration.
        Provided value need to be in specific format.
                value = {
                    'dist_name': '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/RMOD_R-1',
                    'product_code': '475166A.103',
                    'product_name': 'AWEUA',
                    'serial_number': 'AH204500710'
                }
        :param kpi_name: KPI name
        :param value: dict with device info

        """
        mandatory_keys = ['dist_name', 'product_code', 'product_name', 'serial_number']
        missed_keys = [key for key in mandatory_keys if key not in value]
        if missed_keys:
            logging.warning(f"Missing mandatory keys in device_info: {missed_keys}. Skipping update.")
            return

        latest_results_iteration = self.results[kpi_name.lower()][-1]
        latest_results = self.get_latest_results(kpi_name)

        if latest_results_iteration['device_info']:
            logging.warning("Device info already exists in latest iteration. Overwriting is not allowed.")
            return

        latest_results_iteration['device_info'] = value
        latest_results[0]['device_info'] = value

    def calculate_kpi1a(self, ims_file_path, merge_ims_files=False, cell_dist_names=None):
        """
        Calculate KPI1a -Manual Site Reset.
        Start Point: First Cell Down
        End Point: Last Cell Up

        :param str, list ims_file_path: Path to IMS file(or list of ims paths) - for KPI1a you need to use IMS file
                              downloaded via 'collect_infomodel_log_from_current_session'
        :param bool merge_ims_files:  True/False - merge all IMS files into one IMS file before calculations.
        :param list cell_dist_names: list of cell dist names to be considered in the calculation.
                                     If None then all available cells will be used.
        :return list: calculated results for single KPI
        """
        kpi_params = {'kpi1a': {'cell_dist_names': cell_dist_names}}
        return self.calculate_kpis(kpi_names=['kpi1a'], kpi_params=kpi_params, ims_file_path=ims_file_path,
                                   merge_ims_files=merge_ims_files)

