    def calculate_kpi_using_cell_up_down_events(self, cell_down_start_point, cell_up_end_point, kpi_name,
                                                ims_file_path, cell_dist_names=None, merge_ims_files=False):
        """
        Calculate KPI using cell up and down events.
        Start Point: cell_down
        End Point: cell_up

        :param str cell_down_start_point: start_point - possible value 'first' or 'last'
        :param str cell_up_end_point: end_point - possible value 'first' or 'last'
        :param str kpi_name: custom kpi_name - will be visible in results
        :param str, list ims_file_path: Path to IMS file(or list of ims paths)
        :param list cell_dist_names: list of cell dist names to be considered in the calculation.
                                     If None then all available cells will be used.
        :param bool merge_ims_files:  True/False - merge all IMS files into one IMS file before calculations.

        :return list: calculated results for single KPI
        """
        kpi_params = {'kpigenericcell': {
            'kpi_name': kpi_name,
            'cell_down_start_point': cell_down_start_point,
            'cell_up_end_point': cell_up_end_point,
            'cell_dist_names': cell_dist_names
        }}
        return self.calculate_kpis(kpi_names=['kpigenericcell'], kpi_params=kpi_params,
                                   ims_file_path=ims_file_path, merge_ims_files=merge_ims_files)

    @staticmethod
    def get_reset_request_timestamps(ims_file_path):
        """
        Get all RESET timestamp from IMS file.
        NOTE: Reset Request exists only in IMS file downloaded via 'collect_infomodel_log_from_current_session'
        :param ims_file_path: Path to IMS file
        :return list: list of timestamps
        """
        reset_timestamps = []
        for log_entry in Ims2LogReader.from_file(file_path=ims_file_path):
            if isinstance(log_entry, Ims2ResetLogEntry):
                reset_timestamps.append(log_entry.timestamp)
        return reset_timestamps

    @staticmethod
    def _get_current_utc_time():
        return datetime.now(pytz.utc)
